import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Testing and Acceptance System","description":"","frontmatter":{"title":"Testing and Acceptance System"},"headers":[],"relativePath":"guide/testing.md","filePath":"guide/testing.md","lastUpdated":1793266312000}`),a={name:`guide/testing.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_16-testing-and-acceptance-system" tabindex="-1">16. Testing and Acceptance System <a class="header-anchor" href="#_16-testing-and-acceptance-system" aria-label="Permalink to “16. Testing and Acceptance System”">​</a></h1><h2 id="_16-1-unit-tests" tabindex="-1">16.1 Unit tests <a class="header-anchor" href="#_16-1-unit-tests" aria-label="Permalink to “16.1 Unit tests”">​</a></h2><p>Must cover:</p><ul><li>State transitions.</li><li>Dependency verdicts.</li><li>Dependency graph cycle detection.</li><li>AlternativeGroup verdicts.</li><li>Failure thresholds.</li><li>Recovery budgets.</li><li>Candidate plan ordering.</li><li>Notification rules.</li><li>Event deduplication.</li><li>Sensitive data redaction.</li></ul><h2 id="_16-2-integration-tests" tabindex="-1">16.2 Integration tests <a class="header-anchor" href="#_16-2-integration-tests" aria-label="Permalink to “16.2 Integration tests”">​</a></h2><p>Must cover:</p><ul><li>Process Probe.</li><li>Exec Probe.</li><li>Plugin startup failure.</li><li>Plugin output blocking.</li><li>Plugin timeout.</li><li>Plugin crash.</li><li>Resource dependency recovery.</li><li>Multiple upstream resources depending on one resource.</li><li>Concurrent recovery of the same resource.</li><li>Notification queue persistence.</li><li>Database restart recovery.</li><li>Dashboard disabled by default.</li></ul><h2 id="_16-3-fault-injection-tests" tabindex="-1">16.3 Fault injection tests <a class="header-anchor" href="#_16-3-fault-injection-tests" aria-label="Permalink to “16.3 Fault injection tests”">​</a></h2><p>Must simulate:</p><ol><li>A process crash before a recovery action executes.</li><li>A process crash while a recovery action is executing.</li><li>A crash after the action completed but before it was recorded.</li><li>An action succeeding but health verification failing.</li><li>A dependency failing again during recovery.</li><li>A plugin exiting mid-request.</li><li>The network dropping while a notification is being sent.</li><li>A SQLite write failure.</li><li>Multiple tasks requesting recovery of the same resource simultaneously.</li><li>The recovery budget limit being reached.</li></ol><p>Every fault must have explicit expected states and verification assertions.</p><h2 id="_16-4-definition-of-done" tabindex="-1">16.4 Definition of done <a class="header-anchor" href="#_16-4-definition-of-done" aria-label="Permalink to “16.4 Definition of done”">​</a></h2><p>A phase is only complete when:</p><ul><li>The code compiles.</li><li>Formatting checks pass.</li><li>Static checks pass.</li><li>Unit tests pass.</li><li>Integration tests pass.</li><li>Critical failure paths have tests.</li><li>Documentation matches the actual implementation.</li><li>There are no unexplained TODOs or fake capability claims.</li><li>Failures never cause infinite loops.</li><li>Every recovery action has an explicit result.</li><li>Critical state changes are auditable.</li></ul><hr>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};